{"command":"cat > build/fastgcm.c << 'EOF'
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <openssl/aes.h>
#include <openssl/modes.h>
#include <string.h>

void aesni_encrypt(const unsigned char *in, unsigned char *out, const void *key);
int aesni_set_encrypt_key(const unsigned char *userKey, int bits, AES_KEY *key);
void aesni_ctr32_encrypt_blocks(const unsigned char *in, unsigned char *out,
    size_t blocks, const void *key, const unsigned char ivec[16]);

static PyObject *fast_encrypt(PyObject *self, PyObject *args) {
    const unsigned char *key, *nonce, *pt, *aad;
    Py_ssize_t key_len, nonce_len, pt_len, aad_len;

    if (!PyArg_ParseTuple(args, "y#y#y#y#",
                          &key, &key_len,
                          &nonce, &nonce_len,
                          &pt, &pt_len,
                          &aad, &aad_len)) {
        return NULL;
    }
    if (!(key_len == 16 || key_len == 24 || key_len == 32)) {
        PyErr_SetString(PyExc_ValueError, "bad key length");
        return NULL;
    }

    AES_KEY aeskey;
    if (aesni_set_encrypt_key(key, (int)key_len * 8, &aeskey) != 0) {
        PyErr_SetString(PyExc_RuntimeError, "set key failed");
        return NULL;
    }

    GCM128_CONTEXT *ctx = CRYPTO_gcm128_new(&aeskey, (block128_f)aesni_encrypt);
    if (!ctx) {
        PyErr_SetString(PyExc_MemoryError, "gcm ctx");
        return NULL;
    }

    PyObject *ct_obj = PyBytes_FromStringAndSize(NULL, pt_len);
    if (!ct_obj) {
        CRYPTO_gcm128_release(ctx);
        return NULL;
    }
    unsigned char *ct = (unsigned char *)PyBytes_AS_STRING(ct_obj);

    CRYPTO_gcm128_setiv(ctx, nonce, (size_t)nonce_len);
    if (aad_len > 0) {
        if (CRYPTO_gcm128_aad(ctx, aad, (size_t)aad_len) != 0) {
            CRYPTO_gcm128_release(ctx);
            Py_DECREF(ct_obj);
            PyErr_SetString(PyExc_RuntimeError, "aad failed");
            return NULL;
        }
    }
    if (pt_len > 0) {
        if (CRYPTO_gcm128_encrypt_ctr32(ctx, pt, ct, (size_t)pt_len,
                                        (ctr128_f)aesni_ctr32_encrypt_blocks) != 0) {
            CRYPTO_gcm128_release(ctx);
            Py_DECREF(ct_obj);
            PyErr_SetString(PyExc_RuntimeError, "encrypt failed");
            return NULL;
        }
    }
    unsigned char tag[16];
    CRYPTO_gcm128_tag(ctx, tag, 16);
    CRYPTO_gcm128_release(ctx);

    PyObject *tag_obj = PyBytes_FromStringAndSize((const char *)tag, 16);
    if (!tag_obj) {
        Py_DECREF(ct_obj);
        return NULL;
    }
    PyObject *result = PyTuple_New(2);
    if (!result) {
        Py_DECREF(ct_obj);
        Py_DECREF(tag_obj);
        return NULL;
    }
    PyTuple_SET_ITEM(result, 0, ct_obj);
    PyTuple_SET_ITEM(result, 1, tag_obj);
    return result;
}

static PyMethodDef methods[] = {
    {"encrypt", fast_encrypt, METH_VARARGS, "AES-GCM encrypt"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "fastgcm", NULL, -1, methods
};

PyMODINIT_FUNC PyInit_fastgcm(void) {
    return PyModule_Create(&moduledef);
}
EOF
