#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <openssl/aes.h>
#include <openssl/modes.h>

void aesni_encrypt(const unsigned char *in, unsigned char *out, const void *key);
int aesni_set_encrypt_key(const unsigned char *userKey, int bits, AES_KEY *key);
size_t aesni_gcm_encrypt(const unsigned char *in, unsigned char *out, size_t len,
                         const void *key, unsigned char ivec[16], GCM128_CONTEXT *ctx);

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    size_t n = 60ull * 1024 * 1024;
    unsigned char *pt = aligned_alloc(64, n);
    unsigned char *ct = aligned_alloc(64, n);
    memset(pt, 0xab, n);
    unsigned char keyb[16]; memset(keyb, 1, 16);
    unsigned char iv[12]; memset(iv, 2, 12);
    unsigned char aad[32]; memset(aad, 3, 32);

    AES_KEY key;
    aesni_set_encrypt_key(keyb, 128, &key);
    GCM128_CONTEXT *ctx = CRYPTO_gcm128_new(&key, (block128_f)aesni_encrypt);

    /* reference via ctr32 */
    unsigned char *ct_ref = aligned_alloc(64, n);
    CRYPTO_gcm128_setiv(ctx, iv, 12);
    CRYPTO_gcm128_aad(ctx, aad, 32);
    CRYPTO_gcm128_encrypt_ctr32(ctx, pt, ct_ref, n, NULL); /* will use block func? pass NULL carefully */
    /* don't use NULL. redo properly below */

    CRYPTO_gcm128_release(ctx);
    ctx = CRYPTO_gcm128_new(&key, (block128_f)aesni_encrypt);

    /* stitched path: setiv + aad, then aesni_gcm_encrypt on aligned bulk, remainder via encrypt */
    size_t bulk = n & ~(size_t)15; /* multiple of 16, and we'll require >= 0x120? function handles short */
    /* Actually function returns bytes processed. For multiples of 16 it should process all if >= 0x120,
       leaving a tail of at most something. Let's just call and see return value. */

    CRYPTO_gcm128_setiv(ctx, iv, 12);
    CRYPTO_gcm128_aad(ctx, aad, 32);

    /* Need the ivec buffer that setiv produced. It's the first 16 bytes of ctx. */
    unsigned char *ivec = (unsigned char *)ctx;

    double t0 = now();
    size_t done = aesni_gcm_encrypt(pt, ct, n, &key, ivec, ctx);
    double t1 = now();
    printf("one shot done=%zu of %zu  time %.2f ms\n", done, n, (t1-t0)*1000);

    /* finish remainder with generic encrypt and get tag */
    if (done < n) {
        int rc = CRYPTO_gcm128_encrypt(ctx, pt + done, ct + done, n - done);
        printf("remainder rc=%d len=%zu\n", rc, n - done);
    }
    unsigned char tag[16];
    CRYPTO_gcm128_tag(ctx, tag, 16);
    printf("tag: ");
    for (int i = 0; i < 16; i++) printf("%02x", tag[i]);
    printf("\n");

    /* compare with fresh ctx ctr32? ctr32 with NULL is bad. Use encrypt_ctr32 with aesni_ctr32. */
    void aesni_ctr32_encrypt_blocks(const unsigned char *in, unsigned char *out,
        size_t blocks, const void *key, const unsigned char ivec[16]);
    GCM128_CONTEXT *ctx2 = CRYPTO_gcm128_new(&key, (block128_f)aesni_encrypt);
    CRYPTO_gcm128_setiv(ctx2, iv, 12);
    CRYPTO_gcm128_aad(ctx2, aad, 32);
    CRYPTO_gcm128_encrypt_ctr32(ctx2, pt, ct_ref, n, (ctr128_f)aesni_ctr32_encrypt_blocks);
    unsigned char tag2[16];
    CRYPTO_gcm128_tag(ctx2, tag2, 16);
    int match = memcmp(ct, ct_ref, n) == 0 && memcmp(tag, tag2, 16) == 0;
    printf("match vs ctr32: %d\n", match);
    if (!match) {
        for (size_t i = 0; i < n; i++) if (ct[i] != ct_ref[i]) { printf("first mismatch at %zu\n", i); break; }
        printf("tag2: ");
        for (int i = 0; i < 16; i++) printf("%02x", tag2[i]);
        printf("\n");
    }

    /* speed: full operation */
    int reps = 5;
    t0 = now();
    for (int i = 0; i < reps; i++) {
        CRYPTO_gcm128_setiv(ctx, iv, 12);
        CRYPTO_gcm128_aad(ctx, aad, 32);
        size_t d = aesni_gcm_encrypt(pt, ct, n, &key, (unsigned char *)ctx, ctx);
        if (d < n) CRYPTO_gcm128_encrypt(ctx, pt + d, ct + d, n - d);
        CRYPTO_gcm128_tag(ctx, tag, 16);
    }
    t1 = now();
    printf("stitched full: %.2f ms (%.1f MB/s) last done-check tag0=%02x\n",
           (t1-t0)/reps*1000, (n*(double)reps/1e6)/(t1-t0), tag[0]);
    return 0;
}
EOF
