#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <openssl/aes.h>
#include <openssl/modes.h>

void aesni_encrypt(const unsigned char *in, unsigned char *out, const void *key);
int aesni_set_encrypt_key(const unsigned char *userKey, int bits, AES_KEY *key);
size_t aesni_gcm_encrypt(const unsigned char *in, unsigned char *out, size_t len,
                         const void *key, unsigned char ivec[16], GCM128_CONTEXT *ctx);
void aesni_ctr32_encrypt_blocks(const unsigned char *in, unsigned char *out,
    size_t blocks, const void *key, const unsigned char ivec[16]);

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}
static void hex(const char *label, const unsigned char *p, size_t n) {
    printf("%s: ", label);
    for (size_t i = 0; i < n; i++) printf("%02x", p[i]);
    printf("\n");
}

/* Offsets in GCM128_CONTEXT (from disassembly, size 0x1c0):
   0x00  Yi / counter (16)
   0x10  EKi (16)
   0x20  EK0 (16)
   0x30  len.aad (8)
   0x38  len.msg (8)
   0x40  Xi (16)
   0x50  H (16)
   0x60  Htable ...
   0x178 mres
   0x17c ares
   0x180 block func
   0x188 key ptr
   0x190 Xn (16)
*/
#define OFF_MRES 0x178
#define OFF_ARES 0x17c
#define OFF_XI   0x40
#define OFF_XN   0x190
#define OFF_LENMSG 0x38

static int gcm_encrypt_fast(GCM128_CONTEXT *ctx, const AES_KEY *key,
                            const unsigned char *pt, unsigned char *ct, size_t len) {
    unsigned char *c = (unsigned char *)ctx;
    uint32_t *ares = (uint32_t *)(c + OFF_ARES);
    uint32_t *mres = (uint32_t *)(c + OFF_MRES);
    uint64_t *lenmsg = (uint64_t *)(c + OFF_LENMSG);

    if (*ares) {
        /* flush partial AAD into Xi */
        typedef void (*gmult_f)(unsigned char *Xi, const void *Htable);
        /* We don't have the func ptr easily if ares set. For our use aad is multiple of 16
           or we call CRYPTO_gcm128_aad which clears ares when aad%16==0.
           Handle nonzero ares by a tiny dummy? Fall back. */
        return -2;
    }
    *lenmsg += len;

    size_t done = 0;
    if (len >= 32) { /* aesni_gcm_encrypt threshold is 0x120 internally, but call anyway if >=16*8? */
        done = aesni_gcm_encrypt(pt, ct, len, key, c, ctx);
    }
    size_t rem = len - done;
    if (rem) {
        /* tail via generic, which also ghashes the tail and handles partial block.
           BUT generic also adds rem to len.msg. We already added full len. Subtract done? 
           We added full len; generic will add rem again. So subtract rem first. */
        *lenmsg -= rem;
        if (CRYPTO_gcm128_encrypt(ctx, pt + done, ct + done, rem) != 0)
            return -1;
    } else {
        /* no tail: mres stays 0, Xi already updated by asm (it writes Xi). Good.
           len.msg already set. */
    }
    return (int)done;
}

int main() {
    unsigned char keyb[16]; for (int i = 0; i < 16; i++) keyb[i] = i + 1;
    unsigned char iv[12]; for (int i = 0; i < 12; i++) iv[i] = i;
    unsigned char aad[32]; for (int i = 0; i < 32; i++) aad[i] = 0xA0 + i;
    AES_KEY key;
    aesni_set_encrypt_key(keyb, 128, &key);

    size_t sizes[] = {0, 1, 15, 16, 17, 31, 32, 64, 100, 288, 289, 1000, 4096, 4097, 100000};
    int nsizes = sizeof(sizes)/sizeof(sizes[0]);
    int all_ok = 1;
    for (int s = 0; s < nsizes; s++) {
        size_t n = sizes[s];
        unsigned char *pt = calloc(1, n ? n : 1);
        unsigned char *ct = calloc(1, n ? n : 1);
        unsigned char *ct_ref = calloc(1, n ? n : 1);
        for (size_t i = 0; i < n; i++) pt[i] = (unsigned char)(i * 17 + 3);

        GCM128_CONTEXT *ctx = CRYPTO_gcm128_new(&key, (block128_f)aesni_encrypt);
        CRYPTO_gcm128_setiv(ctx, iv, 12);
        CRYPTO_gcm128_aad(ctx, aad, 32);
        int rc = 0;
        if (n) rc = gcm_encrypt_fast(ctx, &key, pt, ct, n);
        else {
            /* nothing */
        }
        unsigned char tag[16];
        CRYPTO_gcm128_tag(ctx, tag, 16);

        GCM128_CONTEXT *ctx2 = CRYPTO_gcm128_new(&key, (block128_f)aesni_encrypt);
        CRYPTO_gcm128_setiv(ctx2, iv, 12);
        CRYPTO_gcm128_aad(ctx2, aad, 32);
        if (n) CRYPTO_gcm128_encrypt_ctr32(ctx2, pt, ct_ref, n, (ctr128_f)aesni_ctr32_encrypt_blocks);
        unsigned char tag2[16];
        CRYPTO_gcm128_tag(ctx2, tag2, 16);

        int ok = (n == 0 || memcmp(ct, ct_ref, n) == 0) && memcmp(tag, tag2, 16) == 0 && rc >= 0;
        printf("n=%zu rc=%d ok=%d\n", n, rc, ok);
        if (!ok) {
            all_ok = 0;
            hex("tag ", tag, 16);
            hex("tag2", tag2, 16);
            if (n) {
                for (size_t i = 0; i < n; i++) if (ct[i] != ct_ref[i]) {
                    printf("  ct mismatch at %zu\n", i); break;
                }
            }
        }
        CRYPTO_gcm128_release(ctx);
        CRYPTO_gcm128_release(ctx2);
        free(pt); free(ct); free(ct_ref);
    }
    printf("ALL OK %d\n", all_ok);

    /* speed */
    size_t n = 60ull * 1024 * 1024;
    unsigned char *pt = aligned_alloc(64, n);
    unsigned char *ct = aligned_alloc(64, n);
    memset(pt, 0x5a, n);
    GCM128_CONTEXT *ctx = CRYPTO_gcm128_new(&key, (block128_f)aesni_encrypt);
    gcm_encrypt_fast(ctx, &key, pt, ct, n); /* warmup, but ctx already used setiv? no, need setiv */
    /* redo properly */
    int reps = 5;
    double t0 = now();
    unsigned char tag[16];
    for (int i = 0; i < reps; i++) {
        CRYPTO_gcm128_setiv(ctx, iv, 12);
        CRYPTO_gcm128_aad(ctx, aad, 32);
        gcm_encrypt_fast(ctx, &key, pt, ct, n);
        CRYPTO_gcm128_tag(ctx, tag, 16);
    }
    double t1 = now();
    printf("fast 60MB: %.2f ms (%.1f MB/s) tag0=%02x\n",
           (t1-t0)/reps*1000, (n*(double)reps/1e6)/(t1-t0), tag[0]);
    return 0;
}
