{"command":"cat > build/full.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <openssl/aes.h>
#include <openssl/modes.h>

void aesni_encrypt(const unsigned char *in, unsigned char *out, const void *key);
int aesni_set_encrypt_key(const unsigned char *userKey, int bits, AES_KEY *key);
void aesni_ctr32_encrypt_blocks(const unsigned char *in, unsigned char *out,
    size_t blocks, const void *key, const unsigned char ivec[16]);
void gcm_init_avx(unsigned char Htable[16*16], const unsigned char H[16]);
void gcm_ghash_avx(unsigned char Xi[16], const unsigned char Htable[16*16],
                   const unsigned char *in, size_t len);
void gcm_gmult_avx(unsigned char Xi[16], const unsigned char Htable[16*16]);

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}
static void hex(const char *l,const unsigned char *p,int n){printf("%s ",l); for(int i=0;i<n;i++) printf("%02x",p[i]); printf("\n");}

static void bswap16(unsigned char *p){
    for (int i=0;i<8;i++){ unsigned char t=p[i]; p[i]=p[15-i]; p[15-i]=t; }
}

static void encrypt_gcm(const unsigned char *keyb, int keybits,
                        const unsigned char *iv, size_t ivlen,
                        const unsigned char *aad, size_t aadlen,
                        const unsigned char *pt, unsigned char *ct, size_t ptlen,
                        unsigned char tag[16]) {
    AES_KEY key;
    aesni_set_encrypt_key(keyb, keybits, &key);

    unsigned char H[16];
    unsigned char zero[16] = {0};
    aesni_encrypt(zero, H, &key);
    /* H in ctx is byte-swapped (big-endian store of the two qwords). Match that. */
    bswap16(H);

    unsigned char Htable[16*16];
    gcm_init_avx(Htable, H);

    unsigned char Xi[16]; memset(Xi, 0, 16);

    /* AAD */
    size_t aad_full = aadlen & ~(size_t)15;
    if (aad_full) gcm_ghash_avx(Xi, Htable, aad, aad_full);
    if (aadlen & 15) {
        unsigned char last[16]; memset(last, 0, 16);
        memcpy(last, aad + aad_full, aadlen & 15);
        gcm_ghash_avx(Xi, Htable, last, 16);
    }

    /* CTR */
    unsigned char ivec[16];
    if (ivlen == 12) {
        memcpy(ivec, iv, 12);
        ivec[12]=0; ivec[13]=0; ivec[14]=0; ivec[15]=1;
    } else {
        /* rare path: GHASH the iv. Not needed for benchmark but handle basically. */
        memset(ivec, 0, 16);
        size_t iv_full = ivlen & ~(size_t)15;
        unsigned char Yi[16]; memset(Yi,0,16);
        if (iv_full) gcm_ghash_avx(Yi, Htable, iv, iv_full);
        if (ivlen & 15) {
            unsigned char last[16]; memset(last,0,16);
            memcpy(last, iv+iv_full, ivlen & 15);
            gcm_ghash_avx(Yi, Htable, last, 16);
        }
        unsigned char lenblock[16]; memset(lenblock,0,16);
        uint64_t ivbits = (uint64_t)ivlen * 8;
        for (int i=0;i<8;i++) lenblock[15-i] = (unsigned char)(ivbits >> (8*i));
        gcm_ghash_avx(Yi, Htable, lenblock, 16);
        /* Yi is in GHASH byte order; counter should be byte-swapped back? 
           For 12-byte we don't use this. Skip correctness for non-12 here. */
        memcpy(ivec, Yi, 16);
    }
    /* encrypt counter 0 for tag mask (J0) */
    unsigned char J0[16]; memcpy(J0, ivec, 16);
    unsigned char EK0[16];
    /* aesni_encrypt expects counter in the same byte order as stored. J0 counter word is big-endian 1. */
    aesni_encrypt(J0, EK0, &key);

    /* increment counter to 2 */
    unsigned char ctr[16]; memcpy(ctr, ivec, 16);
    /* big-endian increment */
    for (int i = 15; i >= 12; i--) { if (++ctr[i]) break; }

    size_t blocks = ptlen / 16;
    size_t rem = ptlen & 15;
    if (blocks) {
        aesni_ctr32_encrypt_blocks(pt, ct, blocks, &key, ctr);
    }
    if (rem) {
        unsigned char ks[16];
        /* ctr was incremented by `blocks` inside ctr32? Does the function update ctr in place? */
        aesni_encrypt(ctr, ks, &key);
        for (size_t i = 0; i < rem; i++) ct[blocks*16 + i] = pt[blocks*16 + i] ^ ks[i];
    }

    /* GHASH ciphertext */
    size_t ct_full = ptlen & ~(size_t)15;
    if (ct_full) gcm_ghash_avx(Xi, Htable, ct, ct_full);
    if (ptlen & 15) {
        unsigned char last[16]; memset(last, 0, 16);
        memcpy(last, ct + ct_full, ptlen & 15);
        gcm_ghash_avx(Xi, Htable, last, 16);
    }

    /* lengths */
    unsigned char lenblock[16]; memset(lenblock, 0, 16);
    uint64_t aadbits = (uint64_t)aadlen * 8;
    uint64_t ctbits = (uint64_t)ptlen * 8;
    for (int i = 0; i < 8; i++) {
        lenblock[7 - i] = (unsigned char)(aadbits >> (8 * i));
        lenblock[15 - i] = (unsigned char)(ctbits >> (8 * i));
    }
    gcm_ghash_avx(Xi, Htable, lenblock, 16);

    /* tag = Xi xor EK0, but Xi is in GHASH byte order (swapped). EK0 is raw AES output.
       The reference Xi we compared earlier matched ghash output directly and tag is
       produced by xoring with EK0 after swapping Xi back? Let's check both if needed.
       From gcm128, Xi is stored byte-swapped (bswap of qwords) and EK0 is raw.
       CRYPTO_gcm128_tag xors them. Our Xi from gcm_ghash_avx matched ctx Xi which is
       the byte-swapped form. EK0 in ctx was raw AES output (we saw f9cc66f3...).
       So tag = bswap(Xi) xor EK0? Or Xi xor EK0?
       We'll compute and compare outside. Store Xi (ghash order) xor EK0 first,
       and also provide swapped variant via a flag. For now output Xi xor EK0. */
    for (int i = 0; i < 16; i++) tag[i] = Xi[i] ^ EK0[i];

    /* also stash swapped tag in... we'll print both in main by recomputing. 
       Let's just also write the swapped-xor into a side channel: overwrite nothing.
       We'll test both in main by calling a variant. */
}

int main(){
    unsigned char keyb[16]; for(int i=0;i<16;i++) keyb[i]=i+1;
    unsigned char iv[12]; for(int i=0;i<12;i++) iv[i]=i;
    unsigned char aad[32]; for(int i=0;i<32;i++) aad[i]=0xA0+i;
    size_t n=1000;
    unsigned char *pt=malloc(n), *ct=malloc(n), *ctref=malloc(n);
    for(size_t i=0;i<n;i++) pt[i]=(unsigned char)(i*17+3);
    unsigned char tag[16];
    encrypt_gcm(keyb, 128, iv, 12, aad, 32, pt, ct, n, tag);

    AES_KEY key; aesni_set_encrypt_key(keyb,128,&key);
    GCM128_CONTEXT *ctx = CRYPTO_gcm128_new(&key,(block128_f)aesni_encrypt);
    CRYPTO_gcm128_setiv(ctx, iv, 12);
    CRYPTO_gcm128_aad(ctx, aad, 32);
    CRYPTO_gcm128_encrypt_ctr32(ctx, pt, ctref, n, (ctr128_f)aesni_ctr32_encrypt_blocks);
    unsigned char tagref[16]; CRYPTO_gcm128_tag(ctx, tagref, 16);
    printf("ct match %d\n", memcmp(ct, ctref, n)==0);
    if (memcmp(ct,ctref,n)){
        for(size_t i=0;i<n;i++) if(ct[i]!=ctref[i]){printf("mismatch %zu got %02x ref %02x\n", i, ct[i], ctref[i]); break;}
    }
    hex("tag   ", tag, 16);
    hex("tagref", tagref, 16);
    unsigned char *c=(unsigned char*)ctx;
    hex("EK0   ", c+0x20, 16);
    hex("Xi fin", c+0x40, 16);
    return 0;
}
EOF
