    for (int i=0;i<16;i++) tag[i] = Xi[i] ^ EK0[i];
    return 0;
}

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

static int check(size_t n, size_t aadlen, int keybits) {
    unsigned char keyb[32]; for (int i=0;i<32;i++) keyb[i]=i+1;
    unsigned char iv[12]; for (int i=0;i<12;i++) iv[i]=i*3+1;
    unsigned char *aad = malloc(aadlen?aadlen:1);
    for (size_t i=0;i<aadlen;i++) aad[i]=(unsigned char)(0xA0+i);
    unsigned char *pt=malloc(n?n:1), *ct=malloc(n?n:1), *ctref=malloc(n?n:1);
    for (size_t i=0;i<n;i++) pt[i]=(unsigned char)(i*17+3);
    unsigned char tag[16], tagref[16];
    int rc = encrypt_gcm(keyb, keybits, iv, 12, aad, aadlen, pt, ct, n, tag);
    AES_KEY key; aesni_set_encrypt_key(keyb, keybits, &key);
    GCM128_CONTEXT *ctx=CRYPTO_gcm128_new(&key,(block128_f)aesni_encrypt);
    CRYPTO_gcm128_setiv(ctx, iv, 12);
    if (aadlen) CRYPTO_gcm128_aad(ctx, aad, aadlen);
    if (n) CRYPTO_gcm128_encrypt_ctr32(ctx, pt, ctref, n, (ctr128_f)aesni_ctr32_encrypt_blocks);
    CRYPTO_gcm128_tag(ctx, tagref, 16);
    int ok = rc==0 && (n==0 || memcmp(ct,ctref,n)==0) && memcmp(tag,tagref,16)==0;
    if (!ok) printf("FAIL n=%zu aad=%zu key=%d rc=%d ct=%d tag=%d\n", n, aadlen, keybits, rc,
                    n?memcmp(ct,ctref,n):0, memcmp(tag,tagref,16));
    CRYPTO_gcm128_release(ctx);
    free(aad); free(pt); free(ct); free(ctref);
    return ok;
}

int main(){
    size_t sizes[]={0,1,15,16,17,31,32,63,64,100,255,256,1000,4095,4096,4097,100000,1000003};
    int all=1;
    for (int kb : (int[]){128,192,256}) {
        for (size_t s=0;s<sizeof(sizes)/sizeof(sizes[0]);s++) {
            for (size_t aadlen : (size_t[]){0,1,13,16,32,33}) {
                if (!check(sizes[s], aadlen, kb)) all=0;
            }
        }
    }
    printf("all ok %d\n", all);

    size_t n=61440000ull;
    unsigned char *pt=aligned_alloc(64,n), *ct=aligned_alloc(64,n);
    memset(pt, 0x5a, n);
    unsigned char keyb[16]; memset(keyb, 7, 16);
    unsigned char iv[12]; memset(iv, 9, 12);
    unsigned char aad[32]; memset(aad, 3, 32);
    unsigned char tag[16];
    encrypt_gcm(keyb,128,iv,12,aad,32,pt,ct,n,tag);
    int reps=5;
    double t0=now();
    for(int i=0;i<reps;i++) encrypt_gcm(keyb,128,iv,12,aad,32,pt,ct,n,tag);
    double t1=now();
    printf("61440000: %.2f ms (%.1f MB/s) tag0=%02x\n", (t1-t0)/reps*1000, (n*(double)reps/1e6)/(t1-t0), tag[0]);

    /* also time reference path for ratio */
    AES_KEY key; aesni_set_encrypt_key(keyb,128,&key);
    GCM128_CONTEXT *ctx=CRYPTO_gcm128_new(&key,(block128_f)aesni_encrypt);
    t0=now();
    for(int i=0;i<reps;i++){
        CRYPTO_gcm128_setiv(ctx, iv, 12);
        CRYPTO_gcm128_aad(ctx, aad, 32);
        CRYPTO_gcm128_encrypt_ctr32(ctx, pt, ct, n, (ctr128_f)aesni_ctr32_encrypt_blocks);
        CRYPTO_gcm128_tag(ctx, tag, 16);
    }
    t1=now();
    printf("ref ctx: %.2f ms\n", (t1-t0)/reps*1000);
    return all?0:1;
}
