{"command":"cat > build/parbench.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>
#include <openssl/aes.h>

void aesni_encrypt(const unsigned char *in, unsigned char *out, const void *key);
int aesni_set_encrypt_key(const unsigned char *userKey, int bits, AES_KEY *key);
void aesni_ctr32_encrypt_blocks(const unsigned char *in, unsigned char *out,
    size_t blocks, const void *key, const unsigned char ivec[16]);
void gcm_init_avx(unsigned char Htable[16*16], const unsigned char H[16]);
void gcm_ghash_avx(unsigned char Xi[16], const unsigned char Htable[16*16],
                   const unsigned char *in, size_t len);

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

#define NTHREADS 4

typedef struct {
    const unsigned char *in;
    unsigned char *out;
    size_t blocks;
    const AES_KEY *key;
    unsigned char ivec[16];
    int tid;
} ctr_job;

static void *ctr_worker(void *arg) {
    ctr_job *j = arg;
    aesni_ctr32_encrypt_blocks(j->in, j->out, j->blocks, j->key, j->ivec);
    return NULL;
}

/* parallel CTR: split into NTHREADS chunks of whole blocks, each with its own starting counter */
static void parallel_ctr(const unsigned char *pt, unsigned char *ct, size_t blocks,
                         const AES_KEY *key, const unsigned char base_ctr[16]) {
    if (blocks < 4096) { /* small: serial */
        aesni_ctr32_encrypt_blocks(pt, ct, blocks, key, base_ctr);
        return;
    }
    pthread_t th[NTHREADS];
    ctr_job jobs[NTHREADS];
    size_t chunk = blocks / NTHREADS;
    size_t off = 0;
    uint32_t c0 = ((uint32_t)base_ctr[12]<<24)|((uint32_t)base_ctr[13]<<16)|((uint32_t)base_ctr[14]<<8)|base_ctr[15];
    int launched = 0;
    for (int t = 0; t < NTHREADS; t++) {
        size_t nb = (t == NTHREADS-1) ? (blocks - off) : chunk;
        jobs[t].in = pt + off*16;
        jobs[t].out = ct + off*16;
        jobs[t].blocks = nb;
        jobs[t].key = key;
        memcpy(jobs[t].ivec, base_ctr, 12);
        uint32_t c = c0 + (uint32_t)off;
        jobs[t].ivec[12]=(unsigned char)(c>>24);
        jobs[t].ivec[13]=(unsigned char)(c>>16);
        jobs[t].ivec[14]=(unsigned char)(c>>8);
        jobs[t].ivec[15]=(unsigned char)c;
        pthread_create(&th[t], NULL, ctr_worker, &jobs[t]);
        launched++;
        off += nb;
    }
    for (int t=0;t<launched;t++) pthread_join(th[t], NULL);
}

typedef struct {
    unsigned char Xi[16];
    const unsigned char *Htable;
    const unsigned char *in;
    size_t len;
} gh_job;

static void *gh_worker(void *arg) {
    gh_job *j = arg;
    memset(j->Xi, 0, 16);
    gcm_ghash_avx(j->Xi, j->Htable, j->in, j->len);
    return NULL;
}

/* GHASH is a chain. Parallelize by computing per-chunk GHASH from Xi=0, then
   combine: Xi_total = Xi0*H^{n1+n2+...} xor Xi1*H^{n2+...} xor ... 
   Combining needs H^k. For a first benchmark, just time the parallel independent
   ghash (lower bound) and a correct combine using serial gmult of powers. */
void gcm_gmult_avx(unsigned char Xi[16], const unsigned char Htable[16*16]);

static void parallel_ghash(unsigned char Xi[16], const unsigned char *Htable,
                           const unsigned char *ct, size_t len) {
    /* len multiple of 16 */
    size_t blocks = len / 16;
    if (blocks < 4096) { gcm_ghash_avx(Xi, Htable, ct, len); return; }
    pthread_t th[NTHREADS];
    gh_job jobs[NTHREADS];
    size_t chunk_blocks = blocks / NTHREADS;
    /* make chunk multiple of ... anything, just 16-byte aligned which it is */
    size_t off = 0;
    for (int t=0;t<NTHREADS;t++) {
        size_t nb = (t==NTHREADS-1) ? (blocks-off) : chunk_blocks;
        jobs[t].Htable = Htable;
        jobs[t].in = ct + off*16;
        jobs[t].len = nb*16;
        pthread_create(&th[t], NULL, gh_worker, &jobs[t]);
        off += nb;
    }
    for (int t=0;t<NTHREADS;t++) pthread_join(th[t], NULL);

    /* Combine. Xi_out = (...((Xi_prev)*H^{nb_i} xor Xi_i) ...)
       Need to multiply an accumulator by H^k. We can do that with k serial gmults — too slow
       for large k. For the benchmark of throughput we first just report independent time
       by not combining. Correctness combine comes next.
       For now, to measure, skip combine. */
    memcpy(Xi, jobs[0].Xi, 16); /* placeholder */
}

int main(){
    size_t n = 61440000ull;
    n = n/16*16;
    unsigned char *pt=aligned_alloc(64,n);
    unsigned char *ct=aligned_alloc(64,n);
    unsigned char *ct2=aligned_alloc(64,n);
    memset(pt, 0x5a, n);
    unsigned char keyb[16]; memset(keyb, 7, 16);
    AES_KEY key; aesni_set_encrypt_key(keyb, 128, &key);
    unsigned char ctr[16]; memset(ctr, 9, 16); ctr[15]=2;

    /* correctness of parallel ctr vs serial */
    aesni_ctr32_encrypt_blocks(pt, ct2, n/16, &key, ctr);
    parallel_ctr(pt, ct, n/16, &key, ctr);
    printf("parallel ctr match %d\n", memcmp(ct, ct2, n)==0);

    int reps=5;
    double t0=now();
    for(int i=0;i<reps;i++) parallel_ctr(pt, ct, n/16, &key, ctr);
    double t1=now();
    printf("parallel ctr %d threads: %.2f ms (%.1f MB/s)\n", NTHREADS, (t1-t0)/reps*1000, (n*(double)reps/1e6)/(t1-t0));

    t0=now();
    for(int i=0;i<reps;i++) aesni_ctr32_encrypt_blocks(pt, ct2, n/16, &key, ctr);
    t1=now();
    printf("serial ctr: %.2f ms (%.1f MB/s)\n", (t1-t0)/reps*1000, (n*(double)reps/1e6)/(t1-t0));

    /* ghash parallel (independent, not combined) timing */
    unsigned char H[16]; memset(H, 0x11, 16);
    unsigned char Ht[256]; gcm_init_avx(Ht, H);
    unsigned char Xi[16]; memset(Xi,0,16);
    t0=now();
    for(int i=0;i<reps;i++){ memset(Xi,0,16); parallel_ghash(Xi, Ht, ct, n); }
    t1=now();
    printf("parallel ghash (no combine): %.2f ms (%.1f MB/s)\n", (t1-t0)/reps*1000, (n*(double)reps/1e6)/(t1-t0));

    t0=now();
    for(int i=0;i<reps;i++){ memset(Xi,0,16); gcm_ghash_avx(Xi, Ht, ct, n); }
    t1=now();
    printf("serial ghash: %.2f ms (%.1f MB/s)\n", (t1-t0)/reps*1000, (n*(double)reps/1e6)/(t1-t0));
    return 0;
}
