#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>
#include <openssl/aes.h>

int aesni_set_encrypt_key(const unsigned char *userKey, int bits, AES_KEY *key);
void aesni_ctr32_encrypt_blocks(const unsigned char *in, unsigned char *out,
    size_t blocks, const void *key, const unsigned char ivec[16]);
void gcm_init_avx(unsigned char Htable[16*16], const unsigned char H[16]);
void gcm_ghash_avx(unsigned char Xi[16], const unsigned char Htable[16*16],
                   const unsigned char *in, size_t len);

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

#define NT 6

typedef struct {
    const unsigned char *pt;
    unsigned char *ct;
    const AES_KEY *key;
    unsigned char ctr[16];
    size_t blocks;
    const unsigned char *Htable;
    unsigned char Xi[16];
    pthread_mutex_t mu;
    pthread_cond_t cv;
    int go, done, stop;
} worker;

static void *worker_fn(void *arg) {
    worker *w = arg;
    pthread_mutex_lock(&w->mu);
    for (;;) {
        while (!w->go && !w->stop) pthread_cond_wait(&w->cv, &w->mu);
        if (w->stop) break;
        w->go = 0;
        pthread_mutex_unlock(&w->mu);
        aesni_ctr32_encrypt_blocks(w->pt, w->ct, w->blocks, w->key, w->ctr);
        memset(w->Xi, 0, 16);
        gcm_ghash_avx(w->Xi, w->Htable, w->ct, w->blocks*16);
        pthread_mutex_lock(&w->mu);
        w->done = 1;
        pthread_cond_signal(&w->cv);
    }
    pthread_mutex_unlock(&w->mu);
    return NULL;
}

int main(){
    size_t n = 61440000ull; n = n/16*16;
    unsigned char *pt=aligned_alloc(64, n);
    unsigned char *ct=aligned_alloc(64, n);
    memset(pt, 0x5a, n);
    unsigned char keyb[16]; memset(keyb, 7, 16);
    AES_KEY key; aesni_set_encrypt_key(keyb, 128, &key);
    unsigned char H[16]; memset(H, 0x11, 16);
    unsigned char Ht[256]; gcm_init_avx(Ht, H);
    unsigned char base[16]; memset(base, 9, 16); base[15]=2;

    worker ws[NT];
    pthread_t th[NT];
    for (int t=0;t<NT;t++) {
        memset(&ws[t], 0, sizeof(ws[t]));
        pthread_mutex_init(&ws[t].mu, NULL);
        pthread_cond_init(&ws[t].cv, NULL);
        pthread_create(&th[t], NULL, worker_fn, &ws[t]);
    }

    int reps=8;
    double t0=now();
    for (int r=0;r<reps;r++) {
        size_t blocks=n/16, chunk=blocks/NT, off=0;
        uint32_t c0=((uint32_t)base[12]<<24)|((uint32_t)base[13]<<16)|((uint32_t)base[14]<<8)|base[15];
        for (int t=0;t<NT;t++) {
            size_t nb=(t==NT-1)?(blocks-off):chunk;
            pthread_mutex_lock(&ws[t].mu);
            ws[t].pt=pt+off*16; ws[t].ct=ct+off*16; ws[t].key=&key; ws[t].blocks=nb; ws[t].Htable=Ht;
            memcpy(ws[t].ctr, base, 12);
            uint32_t c=c0+(uint32_t)off;
            ws[t].ctr[12]=(unsigned char)(c>>24); ws[t].ctr[13]=(unsigned char)(c>>16);
            ws[t].ctr[14]=(unsigned char)(c>>8); ws[t].ctr[15]=(unsigned char)c;
            ws[t].done=0; ws[t].go=1;
            pthread_cond_signal(&ws[t].cv);
            pthread_mutex_unlock(&ws[t].mu);
            off+=nb;
        }
        for (int t=0;t<NT;t++) {
            pthread_mutex_lock(&ws[t].mu);
            while (!ws[t].done) pthread_cond_wait(&ws[t].cv, &ws[t].mu);
            pthread_mutex_unlock(&ws[t].mu);
        }
    }
    double t1=now();
    printf("persistent %d threads ctr+ghash: %.2f ms (%.1f MB/s)\n", NT, (t1-t0)/reps*1000, (n*(double)reps/1e6)/(t1-t0));

    for (int t=0;t<NT;t++) {
        pthread_mutex_lock(&ws[t].mu); ws[t].stop=1; pthread_cond_signal(&ws[t].cv); pthread_mutex_unlock(&ws[t].mu);
        pthread_join(th[t], NULL);
    }
    return 0;
}
