void gcm_ghash_avx(unsigned char Xi[16], const unsigned char Htable[16*16], const unsigned char *in, size_t len);

#define NT 4
typedef struct { const unsigned char *in; unsigned char *out; size_t blocks; const AES_KEY *key; unsigned char ivec[16]; } job;
static void *worker(void *a){ job *j=a; aesni_ctr32_encrypt_blocks(j->in, j->out, j->blocks, j->key, j->ivec); return NULL; }

static void bswap_q(unsigned char *p){ for(int i=0;i<4;i++){ unsigned char t=p[i]; p[i]=p[7-i]; p[7-i]=t; } }
static void bswap16(unsigned char *p){ bswap_q(p); bswap_q(p+8); }

static void parallel_ctr(const unsigned char *pt, unsigned char *ct, size_t blocks,
                         const AES_KEY *key, const unsigned char base[16]) {
    if (blocks < 1024) { aesni_ctr32_encrypt_blocks(pt, ct, blocks, key, base); return; }
    pthread_t th[NT]; job jobs[NT];
    size_t chunk = blocks / NT, off = 0;
    uint32_t c0 = ((uint32_t)base[12]<<24)|((uint32_t)base[13]<<16)|((uint32_t)base[14]<<8)|base[15];
    for (int t=0;t<NT;t++) {
        size_t nb = (t==NT-1)?(blocks-off):chunk;
        jobs[t].in=pt+off*16; jobs[t].out=ct+off*16; jobs[t].blocks=nb; jobs[t].key=key;
        memcpy(jobs[t].ivec, base, 12);
        uint32_t c = c0 + (uint32_t)off;
        jobs[t].ivec[12]=(unsigned char)(c>>24); jobs[t].ivec[13]=(unsigned char)(c>>16);
        jobs[t].ivec[14]=(unsigned char)(c>>8); jobs[t].ivec[15]=(unsigned char)c;
        pthread_create(&th[t], NULL, worker, &jobs[t]);
        off += nb;
    }
    for (int t=0;t<NT;t++) pthread_join(th[t], NULL);
}

static int encrypt(const unsigned char *keyb, int bits, const unsigned char *iv,
                   const unsigned char *aad, size_t aadlen,
                   const unsigned char *pt, unsigned char *ct, size_t ptlen, unsigned char tag[16]) {
    AES_KEY key; if (aesni_set_encrypt_key(keyb, bits, &key)) return -1;
    unsigned char H[16], zero[16]={0};
    aesni_encrypt(zero, H, &key); bswap16(H);
    unsigned char Ht[256]; gcm_init_avx(Ht, H);
    unsigned char Xi[16]; memset(Xi,0,16);
    size_t af=aadlen & ~(size_t)15;
    if (af) gcm_ghash_avx(Xi, Ht, aad, af);
    if (aadlen & 15) { unsigned char last[16]; memset(last,0,16); memcpy(last, aad+af, aadlen&15); gcm_ghash_avx(Xi, Ht, last, 16); }
    unsigned char J0[16]; memcpy(J0, iv, 12); J0[12]=0; J0[13]=0; J0[14]=0; J0[15]=1;
    unsigned char EK0[16]; aesni_encrypt(J0, EK0, &key);
    unsigned char ctr[16]; memcpy(ctr, J0, 16); ctr[15]=2;
    size_t blocks=ptlen/16, rem=ptlen&15;
    if (blocks) {
        parallel_ctr(pt, ct, blocks, &key, ctr);
        uint32_t c=((uint32_t)ctr[12]<<24)|((uint32_t)ctr[13]<<16)|((uint32_t)ctr[14]<<8)|ctr[15];
        c += (uint32_t)blocks;
        ctr[12]=(unsigned char)(c>>24); ctr[13]=(unsigned char)(c>>16); ctr[14]=(unsigned char)(c>>8); ctr[15]=(unsigned char)c;
    }
    if (rem) { unsigned char ks[16]; aesni_encrypt(ctr, ks, &key); for(size_t i=0;i<rem;i++) ct[blocks*16+i]=pt[blocks*16+i]^ks[i]; }
    if (blocks) gcm_ghash_avx(Xi, Ht, ct, blocks*16);
    if (rem) { unsigned char last[16]; memset(last,0,16); memcpy(last, ct+blocks*16, rem); gcm_ghash_avx(Xi, Ht, last, 16); }
    unsigned char lb[16]; memset(lb,0,16);
    uint64_t ab=(uint64_t)aadlen*8, cb=(uint64_t)ptlen*8;
    for(int i=0;i<8;i++){ lb[7-i]=(unsigned char)(ab>>(8*i)); lb[15-i]=(unsigned char)(cb>>(8*i)); }
    gcm_ghash_avx(Xi, Ht, lb, 16);
