    unsigned char H[16], zero[16] = {0};
    aesni_encrypt(zero, H, &aeskey);
    bswap_q(H);
    bswap_q(H + 8);
    unsigned char Htable[16 * 16];
    gcm_init_avx(Htable, H);

    unsigned char Xi[16];
    memset(Xi, 0, 16);
    size_t aad_full = (size_t)aad_len & ~(size_t)15;
    if (aad_full)
        gcm_ghash_avx(Xi, Htable, aad, aad_full);
    if ((size_t)aad_len & 15) {
        unsigned char last[16];
        memset(last, 0, 16);
        memcpy(last, aad + aad_full, (size_t)aad_len & 15);
        gcm_ghash_avx(Xi, Htable, last, 16);
    }

    unsigned char J0[16];
    memcpy(J0, nonce, 12);
    J0[12] = 0; J0[13] = 0; J0[14] = 0; J0[15] = 1;
    unsigned char EK0[16];
    aesni_encrypt(J0, EK0, &aeskey);

    PyObject *ct_obj = PyBytes_FromStringAndSize(NULL, pt_len);
    if (!ct_obj) return NULL;
    unsigned char *ct = (unsigned char *)PyBytes_AS_STRING(ct_obj);

    unsigned char ctr[16];
    memcpy(ctr, J0, 16);
    ctr[15] = 2;

    size_t blocks = (size_t)pt_len / 16;
    size_t rem = (size_t)pt_len & 15;
    if (blocks) {
        parallel_ctr(pt, ct, blocks, &aeskey, ctr);
        uint32_t c = ((uint32_t)ctr[12] << 24) | ((uint32_t)ctr[13] << 16) |
                     ((uint32_t)ctr[14] << 8) | ctr[15];
        c += (uint32_t)blocks;
        ctr[12] = (unsigned char)(c >> 24);
        ctr[13] = (unsigned char)(c >> 16);
        ctr[14] = (unsigned char)(c >> 8);
        ctr[15] = (unsigned char)c;
    }
    if (rem) {
        unsigned char ks[16];
        aesni_encrypt(ctr, ks, &aeskey);
        for (size_t i = 0; i < rem; i++)
            ct[blocks * 16 + i] = pt[blocks * 16 + i] ^ ks[i];
    }

    if (blocks)
        gcm_ghash_avx(Xi, Htable, ct, blocks * 16);
    if (rem) {
        unsigned char last[16];
        memset(last, 0, 16);
        memcpy(last, ct + blocks * 16, rem);
        gcm_ghash_avx(Xi, Htable, last, 16);
    }

    unsigned char lenblock[16];
    memset(lenblock, 0, 16);
    uint64_t aadbits = (uint64_t)aad_len * 8;
    uint64_t ctbits = (uint64_t)pt_len * 8;
    for (int i = 0; i < 8; i++) {
        lenblock[7 - i] = (unsigned char)(aadbits >> (8 * i));
        lenblock[15 - i] = (unsigned char)(ctbits >> (8 * i));
    }
    gcm_ghash_avx(Xi, Htable, lenblock, 16);

    unsigned char tag[16];
    for (int i = 0; i < 16; i++) tag[i] = Xi[i] ^ EK0[i];

    PyObject *tag_obj = PyBytes_FromStringAndSize((const char *)tag, 16);
    if (!tag_obj) { Py_DECREF(ct_obj); return NULL; }
    PyObject *result = PyTuple_New(2);
    if (!result) { Py_DECREF(ct_obj); Py_DECREF(tag_obj); return NULL; }
    PyTuple_SET_ITEM(result, 0, ct_obj);
    PyTuple_SET_ITEM(result, 1, tag_obj);
    return result;
}

static PyMethodDef methods[] = {
    {"encrypt", fast_encrypt, METH_VARARGS, "AES-GCM encrypt"},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {PyModuleDef_HEAD_INIT, "fastgcm", NULL, -1, methods};
PyMODINIT_FUNC PyInit_fastgcm(void) { return PyModule_Create(&moduledef); }
