#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>
#include <openssl/aes.h>
#include <openssl/modes.h>

void aesni_encrypt(const unsigned char *in, unsigned char *out, const void *key);
int aesni_set_encrypt_key(const unsigned char *userKey, int bits, AES_KEY *key);
void aesni_ctr32_encrypt_blocks(const unsigned char *in, unsigned char *out, size_t blocks, const void *key, const unsigned char ivec[16]);
void gcm_init_avx(unsigned char Htable[16*16], const unsigned char H[16]);
void gcm_ghash_avx(unsigned char Xi[16], const unsigned char Htable[16*16], const unsigned char *in, size_t len);
void gcm_gmult_avx(unsigned char Xi[16], const unsigned char Htable[16*16]);

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

/* Multiply Xi by H^k where H is the raw (byte-swapped) hash subkey, using repeated squaring.
   gcm_gmult_avx multiplies by the H baked into Htable. To multiply by an arbitrary X we need
   a table for that X. So: build table for current power, gmult. */
static void mul_pow(unsigned char acc[16], const unsigned char H[16], uint64_t k) {
    /* acc = acc * H^k. Compute H^k by repeated squaring, then one gmult with table of H^k.
       But gmult multiplies Xi by Htable's H. So set Xi = acc, Htable = table(H^k), gmult -> acc*H^k. */
    if (k == 0) return;
    unsigned char base[16]; memcpy(base, H, 16);
    unsigned char result_H[16]; memset(result_H, 0, 16); result_H[0] = 0; /* identity? 
       GHASH identity for multiplication is the element 1, which in reflected representation
       used by OpenSSL is not simply 0x8000... We avoid identity by starting from first set bit. */
    int started = 0;
    unsigned char pow[16]; memcpy(pow, base, 16);
    while (k) {
        if (k & 1) {
            if (!started) { memcpy(result_H, pow, 16); started = 1; }
            else {
                unsigned char Ht[256]; gcm_init_avx(Ht, result_H);
                /* pow = pow * result_H? No: result_H = result_H * pow. */
                unsigned char tmp[16]; memcpy(tmp, pow, 16);
                /* gmult: Xi = Xi * H(Htable). We want result_H * pow.
                   Set Xi = result_H, Htable = table(pow). */
                unsigned char Ht2[256]; gcm_init_avx(Ht2, pow);
                gcm_gmult_avx(result_H, Ht2);
            }
        }
        k >>= 1;
        if (k) {
            unsigned char Ht[256]; gcm_init_avx(Ht, pow);
            gcm_gmult_avx(pow, Ht); /* pow = pow * pow */
        }
    }
    /* acc = acc * result_H */
    unsigned char Ht[256]; gcm_init_avx(Ht, result_H);
    gcm_gmult_avx(acc, Ht);
}

#define NT 4
typedef struct { const unsigned char *in; size_t len; const unsigned char *Ht; unsigned char Xi[16]; } ghjob;
static void *ghfn(void *a){ ghjob *j=a; memset(j->Xi,0,16); gcm_ghash_avx(j->Xi, j->Ht, j->in, j->len); return NULL; }

int main(){
    /* verify combine against serial for a modest buffer */
    size_t n = 1<<20; n = n/16*16;
    unsigned char *buf = aligned_alloc(64, n);
    for (size_t i=0;i<n;i++) buf[i]=(unsigned char)i;
    unsigned char H[16]; for (int i=0;i<16;i++) H[i]=i+1;
    unsigned char Ht[256]; gcm_init_avx(Ht, H);
    unsigned char Xi_ref[16]; memset(Xi_ref,0,16);
    gcm_ghash_avx(Xi_ref, Ht, buf, n);

    pthread_t th[NT]; ghjob jobs[NT];
    size_t blocks=n/16, chunk=blocks/NT, off=0;
    for (int t=0;t<NT;t++) {
        size_t nb=(t==NT-1)?(blocks-off):chunk;
        jobs[t].in=buf+off*16; jobs[t].len=nb*16; jobs[t].Ht=Ht;
        pthread_create(&th[t], NULL, ghfn, &jobs[t]);
        off+=nb;
    }
    for (int t=0;t<NT;t++) pthread_join(th[t], NULL);

    /* combine: acc = 0; for chunk i: acc = acc * H^{nb_i} xor Xi_i */
    unsigned char acc[16]; memset(acc,0,16);
    off=0;
    for (int t=0;t<NT;t++) {
        size_t nb = jobs[t].len/16;
        if (t>0) mul_pow(acc, H, nb); /* wait, should multiply by nb of THIS chunk? 
            acc holds ghash of previous chunks. To shift it across this chunk of nb blocks,
            multiply by H^nb, then xor this chunk's Xi. Yes. */
        for (int i=0;i<16;i++) acc[i]^=jobs[t].Xi[i];
    }
    printf("combine match %d\n", memcmp(acc, Xi_ref, 16)==0);
    printf("ref "); for(int i=0;i<16;i++) printf("%02x", Xi_ref[i]); printf("\n");
    printf("got "); for(int i=0;i<16;i++) printf("%02x", acc[i]); printf("\n");
    return 0;
}
