static void mul_pow(unsigned char acc[16], const unsigned char H[16], uint64_t k) {
    if (k == 0) return;
    unsigned char pow[16]; memcpy(pow, H, 16);
    unsigned char result[16]; int started = 0;
    while (k) {
        if (k & 1) {
            if (!started) { memcpy(result, pow, 16); started = 1; }
            else {
                unsigned char Ht[256]; gcm_init_avx(Ht, pow);
                gcm_gmult_avx(result, Ht); /* result *= pow */
            }
        }
        k >>= 1;
        if (k) {
            unsigned char Ht[256]; gcm_init_avx(Ht, pow);
            gcm_gmult_avx(pow, Ht); /* pow = pow^2 */
        }
    }
    unsigned char Ht[256]; gcm_init_avx(Ht, result);
    gcm_gmult_avx(acc, Ht);
}

