    unsigned char b[64]; for(int i=0;i<64;i++) b[i]=i*3+1;
    unsigned char Xref[16]; memset(Xref,0,16); gcm_ghash_avx(Xref, Ht, b, 64);
    hex("ref", Xref);

    unsigned char X0[16]; memset(X0,0,16); gcm_ghash_avx(X0, Ht, b, 32);      /* first 2 blocks */
    unsigned char X1[16]; memset(X1,0,16); gcm_ghash_avx(X1, Ht, b+32, 32);   /* second 2 blocks */
