void gcm_gmult_avx(unsigned char Xi[16], const unsigned char Htable[16*16]);
static void hex(const char *l,const unsigned char *p){printf("%-14s ",l); for(int i=0;i<16;i++) printf("%02x",p[i]); printf("\n");}
static void mul_pow(unsigned char acc[16], const unsigned char H[16], uint64_t k) {
    printf("enter k=%llu acc0=%02x\n", (unsigned long long)k, acc[0]);
    if (k == 0) return;
    unsigned char pow[16]; memcpy(pow, H, 16);
    unsigned char result[16]; int started = 0; memset(result,0,16);
    int step=0;
    while (k) {
        printf(" step %d k=%llu bit=%llu\n", step, (unsigned long long)k, (unsigned long long)(k&1));
        hex("  pow", pow);
        if (k & 1) {
            if (!started) { memcpy(result, pow, 16); started = 1; hex("  result init", result); }
            else {
                unsigned char Ht[256]; gcm_init_avx(Ht, pow);
                hex("  result before", result);
                gcm_gmult_avx(result, Ht);
                hex("  result after", result);
            }
        }
        k >>= 1;
        if (k) {
            unsigned char base[16]; memcpy(base, pow, 16);
            unsigned char Ht[256]; gcm_init_avx(Ht, base);
            gcm_gmult_avx(pow, Ht);
            hex("  pow squared", pow);
        }
        step++;
    }
    hex("final power", result);
    unsigned char Ht[256]; gcm_init_avx(Ht, result);
    gcm_gmult_avx(acc, Ht);
}
int main(){
